sql.if:
AND (

	(
		JSON_CONTAINS(
			IFNULL(JSON_EXTRACT(${jsonColumn}, '$[*].distributor_id'), JSON_ARRAY()),
			CAST(#{did} AS JSON)
		)
		OR
		JSON_CONTAINS(
			IFNULL(JSON_EXTRACT(${jsonColumn}, '$[*].distributor_id'), JSON_ARRAY()),
			JSON_QUOTE(CAST(#{did} AS CHAR))
		)
	)

)

