mapper.sql:
WHERE 1 = 1
  AND o.company_id = #{filter.companyId}

	AND o.merchant_id = #{filter.merchantId}


	AND o.is_distributor_main = #{filter.isDistributorMain}


	AND o.operator_id IN
	#{oid}


	AND o.mobile = #{filter.mobile}


	AND o.username LIKE CONCAT('%', #{filter.usernameContains}, '%')


	AND o.is_disable = #{filter.isDisable}


	AND o.login_name = #{filter.loginName}


	AND o.role_id = #{filter.roleId}



		AND o.operator_type IS NULL


		AND o.operator_type = #{filter.operatorType}
